const { test } = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');

// The session's ffmpeg arguments, token for token, against test/fixtures/ffmpeg-args-golden.json (generated by the
// 0125 code from test/fixtures/ffmpeg-args-matrix.js; 0144 changed pacing on purpose). This guard went with the
// tuner (a641db0); #322 brings it back to prove that fixing the transcode values (1080p, medium, audio mix auto) and
// removing upscaling left every other play's arguments as they were.
const { TranscodeSession } = require('../server/services/transcodeSession');
const { URL_, matrix, SESSION_DIR } = require('./fixtures/ffmpeg-args-matrix');
const golden = require('./fixtures/ffmpeg-args-golden.json');

function quietly(fn) {
    const log = console.log;
    console.log = () => {};
    try { return fn(); } finally { console.log = log; }
}

test('the golden fixture covers the whole option matrix', () => {
    assert.deepEqual(golden.map(g => g.options), matrix());
    assert.ok(golden.length > 90);
});

test('buildFFmpegArgs produces exactly the golden arguments for every option set', () => {
    for (const { options, args } of golden) {
        const s = new TranscodeSession(URL_, options);
        s.dir = SESSION_DIR;
        s.playlistPath = path.join(SESSION_DIR, 'stream.m3u8');
        assert.deepEqual(quietly(() => s.buildFFmpegArgs()), args, JSON.stringify(options));
    }
});
